class Solution {
public:
    bool strongPasswordCheckerII(std::string password) {
        if (password.size() < 8) return false;
        bool has_lower = false, has_upper = false, has_digit = false, has_special = false;
        std::string specials = "!@#$%^&*()-+";
        for (size_t i = 0; i < password.size(); ++i) {
            char c = password[i];
            if (i > 0 && c == password[i - 1]) return false;
            if (islower(c)) has_lower = true;
            else if (isupper(c)) has_upper = true;
            else if (isdigit(c)) has_digit = true;
            else if (specials.find(c) != std::string::npos) has_special = true;
        }
        return has_lower && has_upper && has_digit && has_special;
    }
};

class Solution {
    public boolean strongPasswordCheckerII(String password) {
        if (password.length() < 8) return false;
        boolean hasLower = false, hasUpper = false, hasDigit = false, hasSpecial = false;
        String specials = "!@#$%^&*()-+";
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (i > 0 && c == password.charAt(i - 1)) return false;
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;
            else if (specials.indexOf(c) != -1) hasSpecial = true;
        }
        return hasLower && hasUpper && hasDigit && hasSpecial;
    }
}

var strongPasswordCheckerII = function(password) {
    if (password.length < 8) return false;
    let hasLower = false, hasUpper = false, hasDigit = false, hasSpecial = false;
    const specials = new Set("!@#$%^&*()-+");
    for (let i = 0; i < password.length; i++) {
        const c = password[i];
        if (i > 0 && c === password[i - 1]) return false;
        if (c >= 'a' && c <= 'z') hasLower = true;
        else if (c >= 'A' && c <= 'Z') hasUpper = true;
        else if (c >= '0' && c <= '9') hasDigit = true;
        else if (specials.has(c)) hasSpecial = true;
    }
    return hasLower && hasUpper && hasDigit && hasSpecial;
};
